using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System.IO;using Abyss.Story;
namespace Abyss.EditorTools {
[InitializeOnLoad] public static class Revision14Setup {
 static Revision14Setup(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("R14",false)){SessionState.SetBool("R14",false);Application.runInBackground=true;Camera.main.gameObject.AddComponent<Revision14Verification>();}};EditorApplication.update+=()=>{var p="Temp/revision14-command.txt";if(!File.Exists(p)||EditorApplication.isCompiling||EditorApplication.isUpdating)return;var c=File.ReadAllText(p).Trim();File.Delete(p);if(c=="apply"){if(EditorApplication.isPlaying)return;var e=Object.FindFirstObjectByType<WarEnvironment>();if(e.gameObject.scene.path!="Assets/Scenes/UnderwaterWorld.unity")return;e.pollutionShader=Shader.Find("Abyss/PollutedBackground");e.maximumWaste=64;e.maximumCorpses=8;e.canFrequencyMultiplier=3.5f;e.announcementWaste=10;e.journeyWaste=52;e.wasteInterval=1.3f;EditorSceneManager.MarkSceneDirty(e.gameObject.scene);EditorSceneManager.SaveScene(e.gameObject.scene);}if(c=="verify"){Application.runInBackground=true;SessionState.SetBool("R14",true);EditorApplication.isPlaying=true;}};}
}}
